          <motion.div key={i} className="shape-layer" style={{ y: ys[i] }}>
            <div className={calm ? "shape-layer" : "shape-layer breathe"} style={{ animationDelay: `${-i * 0.45}s` }}>
              <svg viewBox="0 0 400 460">
