      </radialGradient>
      <radialGradient id="lw-g-shadow" cx="0.5" cy="0.5" r="0.5">
        <stop offset="0" stopColor="rgba(60,40,10,0.26)" />
        <stop offset="1" stopColor="rgba(60,40,10,0)" />
      </radialGradient>
    </defs>
  );
}

