:root {
  --bg: #fbf8f3; --paper: #ffffff; --ink: #1d1a16; --ink-2: #57514a; --muted: #7a736b;
  --line: #ebe4da; --line-2: #ddd4c8; --primary: #1d1a16; --primary-ink: #ffffff;
  --wa: #128c4a; --focus: #2563eb; --radius: 18px; --radius-sm: 12px;
  --shadow: 0 1px 2px rgba(40,30,20,.05), 0 10px 30px -18px rgba(40,30,20,.25);
  --serif: "Iowan Old Style", "Palatino Linotype", Palatino, Georgia, "Noto Serif", serif;
  --sans: system-ui, -apple-system, "Segoe UI", Roboto, "Noto Sans", "Helvetica Neue", sans-serif;
  /* Fixed category palette (soft background, strong ink), assigned by position. */
  --c0-bg: #fde8d7; --c0-ink: #9a3412;
  --c1-bg: #dff3e4; --c1-ink: #166534;
  --c2-bg: #e3ecfb; --c2-ink: #1e40af;
  --c3-bg: #f6e3f0; --c3-ink: #9d174d;
  --c4-bg: #fbf1c7; --c4-ink: #854d0e;
    <section class="about" id="about" aria-labelledby="about-h">
      <h2 class="section-h" id="about-h">About us</h2>
      <div class="prose">{% for para in p.about.split("\n") if para.strip() %}<p>{{ para }}</p>{% endfor %}</div>
    </section>
    {% endif %}

    <section class="about" id="info" aria-labelledby="info-h">
      <h2 class="section-h" id="info-h">Visit, contact &amp; pay</h2>
      <div class="info">
        {% if p.hours or p.area %}<div class="tile">
          <h3>{% if p.hours %}Open{% else %}Where{% endif %}</h3>
          {% if p.hours %}<p>{{ p.hours }}</p>{% endif %}
          {% if p.area %}<p{% if p.hours %} class="hint" style="margin-top:6px"{% endif %}>{{ p.area }}</p>{% endif %}
        </div>{% endif %}
        {% if p.pickup_available or p.delivery_available %}<div class="tile">
          <h3>Getting your order</h3>
          {% if p.pickup_available %}<p>Pickup{% if p.area %} from {{ p.area }}{% endif %}</p>{% endif %}
          {% if p.delivery_available %}<p>Delivery{% if p.delivery_fee_inr %}: {{ p.delivery_fee_inr | inr }}{% else %}: free{% endif %}</p>{% endif %}
        </div>{% endif %}
        {% if p.phone or whatsapp_url %}<div class="tile">
          <h3>Contact</h3>
          {% if p.phone %}<p>{{ p.phone }}</p>{% endif %}
          <div class="links">
            {% if p.phone %}<a class="btn btn-line btn-sm" href="tel:{{ p.phone | replace(' ', '') }}">{{ icon("phone") }}Call</a>{% endif %}
            {% if whatsapp_url %}<a class="btn btn-wa btn-sm" href="{{ whatsapp_url }}" target="_blank" rel="noopener">{{ icon("wa") }}WhatsApp</a>{% endif %}
          </div>
        </div>{% endif %}
        {% if upi %}<div class="tile wide" id="pay">
          <h3>Pay by UPI</h3>
          <div class="pay">
            {{ upi_qr }}
            <div>
              <p>Scan with any UPI app, or <a href="{{ upi }}">open your UPI app</a>.</p>
              <p class="upi-name">UPI ID: <span class="upi-id">{{ p.upi_id }}</span></p>
              {% if p.upi_display_name %}<p class="upi-name">Your UPI app should show: <strong>{{ p.upi_display_name }}</strong></p>{% endif %}
              <p class="hint" style="margin-top:6px">Please confirm the amount with us before paying.</p>
            </div>
          </div>
        </div>{% endif %}
      </div>
    </section>
  </div>

  <aside class="panel" id="order" aria-labelledby="order-h">
    <h2 id="order-h">Your order</h2>
    <p class="hint" style="margin:0">Nothing is charged here. We'll contact you to confirm the order and payment.</p>

